package com.cloud.ffo;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.net.*;
public class MainActivity extends Activity {
 private TextView state;private Button launch,start,download,stop;private final Handler handler=new Handler();private boolean resumed;
 private final Runnable poll=new Runnable(){public void run(){if(!resumed||state==null||!AccessGate.unlocked)return;new Thread(()->{boolean healthy=false;try{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:11880/health").openConnection();c.setConnectTimeout(900);c.setReadTimeout(900);healthy=c.getResponseCode()==200;c.disconnect();}catch(Exception ignored){}final boolean ok=healthy;runOnUiThread(()->{state.setText(ok?"Local server is ready\nYour progress is saved on this phone.":ServerService.status);launch.setEnabled(ok);boolean busy=ServerService.status.startsWith("Preparing")||ServerService.status.startsWith("Downloading")||ServerService.status.startsWith("Reading");start.setEnabled(!ok&&!busy);download.setEnabled(!ok&&!busy);stop.setEnabled(ok);});}).start();handler.postDelayed(this,1500);}};
 public void onCreate(Bundle b){super.onCreate(b);showGate();}
 private void showGate(){AccessGate.unlocked=false;LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(24),dp(48),dp(24),dp(24));panel.setBackgroundColor(Color.rgb(10,18,32));setContentView(panel);panel.addView(text("FF:O · Tester access",28));EditText input=new EditText(this);input.setSingleLine(true);input.setHint("Tester password");input.setTextColor(Color.WHITE);input.setHintTextColor(Color.LTGRAY);input.setInputType(129);panel.addView(input);TextView error=text("Enter the password provided by Cloud.",14);panel.addView(error);button(panel,"Unlock Hub").setOnClickListener(v->{if(AccessGate.check(input.getText().toString())){AccessGate.unlocked=true;input.setText("");showHub();handler.post(poll);}else{error.setText("Incorrect password. Try again.");input.setText("");}});}
 private void showHub(){getExternalFilesDir(null);if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(32),dp(24),dp(24));root.setBackgroundColor(Color.rgb(10,18,32));setContentView(root);
 TextView title=text("FF:O",38);title.setTypeface(null,Typeface.BOLD);root.addView(title);root.addView(text("BRAVE EXVIUS · OFFLINE",13));
 TextView note=text("Your adventure, on your phone.",18);note.setPadding(0,26,0,32);root.addView(note);state=text("Checking local server…",18);state.setPadding(16,22,16,22);root.addView(state);
 download=button(root,"Download / repair game data");download.setOnClickListener(v->{startForegroundService(new Intent(this,ServerService.class).setAction("download"));});
 start=button(root,"Start server");start.setOnClickListener(v->{ServerService.status="Preparing server…";startForegroundService(new Intent(this,ServerService.class));start.setEnabled(false);});
 launch=button(root,"Launch FF:O");launch.setEnabled(false);launch.setOnClickListener(v->{Intent game=getPackageManager().getLaunchIntentForPackage("com.square_enix.android_googleplay.FFBEWW");if(game==null)new AlertDialog.Builder(this).setMessage("Install FF:O-Client.apk first.").setPositiveButton("OK",null).show();else startActivity(game);});
 stop=button(root,"Stop server");stop.setOnClickListener(v->stopService(new Intent(this,ServerService.class)));
 TextView footer=text("Start the server, wait for Ready, then launch.\nKeep the server notification active while playing.\n\nTest build · placeholder content included",13);footer.setPadding(0,32,0,0);root.addView(footer);
 }
 private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density+0.5f);}
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.rgb(219,230,245));return v;}
 private Button button(LinearLayout root,String label){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(17);b.setTextColor(Color.WHITE);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.rgb(36,78,111));bg.setCornerRadius(18);b.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(56));p.setMargins(0,dp(12),0,0);root.addView(b,p);return b;}
 public void onResume(){super.onResume();resumed=true;handler.post(poll);}public void onPause(){resumed=false;handler.removeCallbacks(poll);super.onPause();}
}
